public static long nthPrime(int n){
  if (n < 1) {
    throw new IllegalArgumentException("n must be positive");
  }
  long prime = 2;
  long count = 1;
  while (count < n) {
    prime++;
    boolean isPrime = true;
    for (long i = 2; i <= Math.sqrt(prime); i++) {
      if (prime % i == 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      count++;
    }
  }
  return prime;
}

