 * @param byteOffset     index of the first byte of byteArrayValue that must be copied.
 * @param byteLength     number of bytes of byteArrayValue that must be copied.
 * @return this byte vector.
 */
public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        byte[] nullBytes = new byte[byteLength];
        Arrays.fill(nullBytes, (byte) 0);
        putByteArray(nullBytes, 0, byteLength);
        return this;
    }

    int startIndex = byteOffset;
    int length = Math.min(byteArrayValue.length - startIndex, byteLength);
    int requiredLength = startIndex + length;

    if (requiredLength > this.data.length) {
        grow(requiredLength);
    }

    System.arraycopy(byteArrayValue, startIndex, this.data, startIndex, length);
    this.count = Math.max(this.count, requiredLength);
    return this;
}

