protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    Map<E, ForwardNode<V, E>> nodeMap = new LinkedHashMap<>();
    Map<E, ForwardNode<V, E>> edgeMap = new LinkedHashMap<>();
    Set<ForwardNode<V, E>> endNodes = new HashSet<>();

    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        nodeMap.putIfAbsent(source, new ForwardNode<>(source));
        nodeMap.putIfAbsent(target, new ForwardNode<>(target));
        ForwardNode<V, E> sourceNode = nodeMap.get(source);
        ForwardNode<V, E> targetNode = nodeMap.get(target);
        ForwardEdge<V, E> forwardEdge = new ForwardEdge<>(edge, sourceNode, targetNode);
        sourceNode.addSuccessor(forwardEdge);
        targetNode.addPredecessor(forwardEdge);
        edgeMap.put(edge, forwardEdge);
        endNodes.add(sourceNode);
        endNodes.add(targetNode);
    }

    GraphPath<V, E> graphPath = new GraphPath<>(endNodes);
    for (E edge : tour) {
        ForwardNode<V, E> sourceNode = edgeMap.get(edge).getSource();
        ForwardNode<V, E> targetNode = edgeMap.get(edge).getTarget();
        graphPath.addEdge(edge, sourceNode.getVertex(), targetNode.getVertex());
    }

    return graphPath;
}

