public class ProfileParser {

private static final String TIMESTAMP_PREFIX = "TIMESTAMP:";
private static final String THREAD_ID_PREFIX = "THREAD ID:";
private static final String THREAD_NAME_PREFIX = "THREAD NAME:";
private static final String CPU_USAGE_PREFIX = "CPU USAGE:";
private static final String CPU_DESC_PREFIX = "CPU DESC:";
private static final String STACK_TRACE_PREFIX = "STACK TRACE:";

/**
 * Parses a profile file and returns a list of thread snapshots within the given time range.
 *
 * @param file The profile file to parse.
 * @param timeRanges The time ranges to search for thread snapshots.
 * @return A list of thread snapshots within the given time range.
 * @throws IOException If an I/O error occurs.
 */
public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith(TIMESTAMP_PREFIX)) {
                String timestamp = line.substring(TIMESTAMP_PREFIX.length());
                if (matchesTimeRange(timestamp, timeRanges)) {
                    threadSnapshots.add(parseThreadSnapshot(reader));
                    break;
                }
            }
        }
    }
    return threadSnapshots;
}

/**
 * Checks if the given timestamp matches any of the given time ranges.
 *
 * @param timestamp The timestamp to check.
 * @param timeRanges The time ranges to search for thread snapshots.
 * @return True if the given timestamp matches any of the given time ranges, false otherwise.
 */
private static boolean matchesTimeRange(String timestamp, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timeRange.contains(timestamp)) {
            return true;
        }
    }
    return false;
}

/**
 * Parses a thread snapshot from the given reader.
 *
 * @param reader The reader to parse from.
 * @return A thread snapshot parsed from the given reader.
 * @throws IOException If an I/O error occurs.
 */
private static ThreadSnapshot parseThreadSnapshot(BufferedReader reader) throws IOException {
    ThreadSnapshot threadSnapshot = new ThreadSnapshot();
    String line = reader.readLine();
    if (line != null) {
        if (line.startsWith(THREAD_ID_PREFIX)) {
            threadSnapshot.setThreadId(Integer.parseInt(line.substring(THREAD_ID_PREFIX.length())));
        } else if (line.startsWith(THREAD_NAME_PREFIX)) {
            threadSnapshot.setThreadName(line.substring(THREAD_NAME_PREFIX.length()));
        } else if (line.startsWith(CPU_USAGE_PREFIX)) {
            threadSnapshot.setCpuUsage(Float.parseFloat(line.substring(CPU_USAGE_PREFIX.length())));
        } else if (line.startsWith(CPU_DESC_PREFIX)) {
            threadSnapshot.setCpuDesc(line.substring(CPU_DESC_PREFIX.length()));
        } else if (line.startsWith(STACK_TRACE_PREFIX)) {
            threadSnapshot.setStackTrace(line.substring(STACK_TRACE_PREFIX.length()));
        }
    }
    return threadSnapshot;
}
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    /**
     * Read file content into list
     */
    List<String> fileContent = Files.readAllLines(file.toPath());

    /**
     * Declare list to store thread snapshots
     */
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    /**
     * Iterate over each line in file content
     */
    for (String line : fileContent) {

        /**
         * Split line into tokens by space delimiter
         */
        String[] tokens = line.split(" ");

        /**
         * Check if line contains at least 3 tokens
         */
        if (tokens.length > 2) {

            /**
             * Extract start time, end time, and thread name from tokens
             */
            long startTime = Long.parseLong(tokens[0]);
            long endTime = Long.parseLong(tokens[2]);
            String threadName = tokens[3];

            /**
             * Check if thread snapshot time range matches with profile analyze time range
             */
            boolean matches = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (startTime >= timeRange.getStartTime() && endTime <= timeRange.getEndTime()) {
                    matches = true;
                    break;
                }
            }

            /**
             * Create and add thread snapshot to list if match found
             */
            if (matches) {
                threadSnapshots.add(new ThreadSnapshot(threadName, startTime, endTime));
            }
        }
    }

    /**
     * Return list of thread snapshots
     */
    return threadSnapshots;
